//! 🧪️ Genuine native slots retain originals under foreign, underfunded and outstanding-reader refusals.
use super::*;
fn grant(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes+d.capacity_bytes<=4096);RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth.max(1)}}
#[test]
fn original_slot_preserves_native_payload_and_waits_for_every_projected_reader(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();assert_eq!(law["policy"]["maximumItems"],1);
 let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<String>>=Arc::new(crate::retirement::OwnedValueRetirementFactory::<String>::default());
 let mut original=RetainedOriginalSlot::new("original α\0😀".repeat(8192));let pointer=original.get().as_ptr();let key=original.key();let foreign=RetainedOriginalSlot::new(String::new()).key();assert!(original.demands(foreign).is_err());
 for _ in 0..2{let d=original.demands(key).unwrap();for axis in 0..5{let mut denied=grant(d);match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>denied.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>denied.maximum_depth=d.depth-1,_=>continue}let(step,heap)=crate::observe_retirement_allocations(||original.advance_read(key,&factory,denied).unwrap());assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!(heap,(0,0));assert_eq!(original.get().as_ptr(),pointer);}
  let(step,heap)=crate::observe_retirement_allocations(||original.advance_read(key,&factory,grant(d)).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}
 let(mut lease,_)=original.borrow(key).unwrap().retain_projection(grant(crate::retained_clone::RetainedOwnedProjection::<String>::constructor_demand())).unwrap();assert_eq!(lease.borrow().unwrap().get().as_ptr(),pointer);
 let mut next=Some("next".to_string());let next_error=original.replace(&mut next,grant(RetainedOriginalSlot::<String>::replace_demand())).unwrap_err();assert_eq!(next_error.kind,ValueRefusalKind::InvariantViolated);assert_eq!(next.as_deref(),Some("next"));assert_eq!(original.get().as_ptr(),pointer);let mut returned=None;
 for _ in 0..8{let d=original.return_demands(key,4096).unwrap();let(step,heap)=crate::observe_retirement_allocations(||original.return_read(key,&mut returned,grant(d)).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(returned.is_none());assert_eq!(original.get().as_ptr(),pointer);}
 for _ in 0..10000{if lease.terminal_is_empty(){break;}let d=lease.close_demand(4096).unwrap();let(step,heap)=crate::observe_retirement_allocations(||lease.close_step(grant(d)).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(lease.terminal_is_empty());
 for _ in 0..10000{if !original.has_read(){break;}let d=original.return_demands(key,4096).unwrap();let(step,heap)=crate::observe_retirement_allocations(||original.return_read(key,&mut returned,grant(d)).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(!original.has_read());assert!(Arc::ptr_eq(returned.as_ref().unwrap(),&factory));assert_eq!(original.get().as_ptr(),pointer);
 let mut issuer=crate::FactoryAuthority::new(returned.take().unwrap());while !issuer.terminal_is_empty(){let d=issuer.demands(4096).unwrap();issuer.step(grant(d)).unwrap();}
 let value=original.try_into_original().unwrap_or_else(|_|panic!("returned original slot remains uniquely owned"));assert_eq!(value.as_ptr(),pointer);let mut close=crate::retirement::controlled::ControlledRetirement::new(value).map_err(|(e,_)|e).unwrap();while !close.terminal_is_empty(){let d=close.next_demand(4096).unwrap();let(step,heap)=crate::observe_retirement_allocations(||close.step(grant(d)).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}
 eprintln!("[DEBUG] Actual original slot retained giant UTF8 native pointer through denied currencies and foreign source; same issuer returned only after projected read closure");
}
#[test]
fn original_slot_generation_exhaustion_refuses_before_native_exchange(){let mut original=RetainedOriginalSlot::new(7u64);original.generation=u64::MAX;let key=original.key();let mut next=Some(9);let error=original.replace(&mut next,grant(RetainedOriginalSlot::<u64>::replace_demand())).unwrap_err();assert_eq!(error.kind,ValueRefusalKind::InvariantViolated);assert_eq!((original.get(),next,original.key()),(&7,Some(9),key));eprintln!("[DEBUG] Original slot generation exhaustion returned authored replacement and preserved source exactly");}

#[test]
fn original_slot_exchange_matches_all_independent_portable_outputs(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();
 for law in corpus["cases"].as_array().unwrap(){let mut slot=RetainedOriginalSlot::new(serde_json::to_string(&law["original"]).unwrap());let old_pointer=slot.get().as_ptr();let key=slot.key();let mut next=Some(serde_json::to_string(&law["replacement"]).unwrap());let next_pointer=next.as_ref().unwrap().as_ptr();let d=RetainedOriginalSlot::<String>::replace_demand();
  for axis in [0,1,4]{let mut denied=grant(d);match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes-=1,_=>denied.maximum_depth-=1}let(result,heap)=crate::observe_retirement_allocations(||slot.replace(&mut next,denied).unwrap());assert!(result.is_none());assert_eq!(heap,(0,0));assert_eq!(slot.get().as_ptr(),old_pointer);assert_eq!(next.as_ref().unwrap().as_ptr(),next_pointer);assert_eq!(slot.key(),key);}
  let(result,heap)=crate::observe_retirement_allocations(||slot.replace(&mut next,grant(d)).unwrap());let(previous,p)=result.unwrap();assert_eq!(heap,(0,0));assert_eq!(p.copied_bytes,d.copy_bytes);assert_eq!(p.copied_items,1);assert!(next.is_none());assert_eq!(previous.as_ptr(),old_pointer);assert_eq!(slot.get().as_ptr(),next_pointer);assert_ne!(slot.key(),key);assert_eq!(serde_json::from_str::<serde_json::Value>(slot.get()).unwrap(),law["expected"]);
  let current=slot.try_into_original().unwrap_or_else(|_|panic!("portable exchange original remains uniquely owned"));for original in [previous,current]{let mut close=crate::retirement::controlled::ControlledRetirement::new(original).map_err(|(e,_)|e).unwrap();while !close.terminal_is_empty(){let d=close.next_demand(4096).unwrap();let(step,heap)=crate::observe_retirement_allocations(||close.step(grant(d)).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}}
 }
 eprintln!("[DEBUG] Original slot four portable native outputs match independent RFC6902 corpus; denied exchange preserves both source allocation identities");
}

static RETIRED_POINTER:std::sync::atomic::AtomicUsize=std::sync::atomic::AtomicUsize::new(0);
#[derive(crate::FactoryPayloadRetirement)]
struct OriginalIssuer;
impl ArtifactOwnedValueRetirementFactory<String> for OriginalIssuer{fn retirement_birth_bytes(&self,_:&String)->usize{crate::retirement::owned_retirement_birth_bytes::<String>()}fn retire_owned(&self,value:String,g:RetainedCloneGrant)->Result<(Box<dyn crate::ErasedSnapshotRetirement>,RetainedCloneProgress),(ValueError,String)>{RETIRED_POINTER.store(value.as_ptr()as usize,std::sync::atomic::Ordering::Relaxed);crate::retirement::admit_owned_retirement(value,g)}}
#[test]
fn original_slot_retirement_returns_all_readers_then_uses_same_captured_payload_issuer(){
 for prefix in [0,1,2]{RETIRED_POINTER.store(0,std::sync::atomic::Ordering::Relaxed);let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<String>>=Arc::new(OriginalIssuer);let mut slot=RetainedOriginalSlot::new("original cancelled α\0😀".repeat(8192));let pointer=slot.get().as_ptr()as usize;let key=slot.key();for _ in 0..prefix{let d=slot.demands(key).unwrap();slot.advance_read(key,&factory,grant(d)).unwrap();}
  let mut projection=if prefix==2{Some(slot.borrow(key).unwrap().retain_projection(grant(crate::retained_clone::RetainedOwnedProjection::<String>::constructor_demand())).unwrap().0)}else{None};let mut owner=crate::retirement::controlled::ControlledRetirement::new(slot).map_err(|(e,_)|e).unwrap();
  for turn in 0..10000{if turn==5{if let Some(projection)=projection.as_mut(){while !projection.terminal_is_empty(){let d=projection.close_demand(4096).unwrap();let(step,heap)=crate::observe_retirement_allocations(||projection.close_step(grant(d)).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}}projection=None;}
   if owner.terminal_is_empty(){break;}let d=owner.next_demand(4096).unwrap();for axis in 0..5{let mut denied=grant(d);match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes-=1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes-=1,3 if d.release_bytes>0=>denied.maximum_release_bytes-=1,4 if d.depth>0=>denied.maximum_depth-=1,_=>continue}let(result,heap)=crate::observe_retirement_allocations(||owner.step(denied));match result{Ok(step)=>assert_eq!(step.progress(),RetainedCloneProgress::default()),Err(error)=>assert_eq!(error.retained_progress(),RetainedCloneProgress::default())}assert_eq!(heap,(0,0));}
   let(step,heap)=crate::observe_retirement_allocations(||owner.step(grant(d)).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));if projection.is_some(){assert_eq!(RETIRED_POINTER.load(std::sync::atomic::Ordering::Relaxed),0);}
  }assert!(owner.terminal_is_empty());assert!(projection.is_none());assert_eq!(RETIRED_POINTER.load(std::sync::atomic::Ordering::Relaxed),if prefix==0{0}else{pointer});let mut issuer=crate::FactoryAuthority::new(factory);while !issuer.terminal_is_empty(){issuer.step(grant(issuer.demands(4096).unwrap())).unwrap();}
 }
 eprintln!("[DEBUG] Original slot cancellation at all three read birth prefixes returned every lease before same-issuer payload retirement; every actual currency matched native System heap");
}
